#include <iostream>
#include <string>
#include <vector>

struct Registro {
    std::string codigo;
    int unidades;
};

void procesar(const std::vector<Registro>& registros) {
    int total = 0;
    std::vector<Registro> elegidos;
    std::cout << "Datos:";
    for (const auto& registro : registros) {
        std::cout << registro.codigo << ":" << registro.unidades << ";";
        total += registro.unidades;
        if (registro.unidades >= 4) { elegidos.push_back(registro); }
    }
    std::cout << "\nTotal:" << total << "\nElegidos:";
    for (const auto& registro : elegidos) {
        std::cout << registro.codigo << ":" << registro.unidades << ";";
    }
    std::cout << "\n";
}

int main() {
    procesar({{"A", 2}, {"B", 7}, {"A", 4}});
    procesar({});
    procesar({{"Z", 0}});
    procesar({{"R", 1}, {"R", 5}});
    return 0;
}

#include <iostream>
#include <string>
#include <vector>

struct Registro {
    std::string codigo;
    int unidades;
};

void presentar(const std::vector<Registro>& registros) {
    for (const auto& registro : registros) {
        std::cout << registro.codigo << ":" << registro.unidades << ";";
    }
}

int main() {
    std::vector<Registro> original{{"C", 2}, {"D", 1}};
    const std::vector<Registro> copia = original;
    original.at(0).unidades += 3;
    std::cout << "Original:";
    presentar(original);
    std::cout << "\nCopia:";
    presentar(copia);
    return 0;
}
